library(zuutf)
d <- function(s, ...) tryCatch(paste(as.character(base64_decode(s, ...)), collapse=""), zuutf_base64_error = function(e) paste0("offset ", e$offset))
cat("strict, '*' at 1 and ' ' at 5:   ", d("*UJD QUJD", forgiving = FALSE), " (first offending char is 1)\n")
cat("strict, '*' at 1, no whitespace: ", d("*UJDQUJD", forgiving = FALSE), "\n")
cat("pad=FALSE, '*' at 1, length 5:   ", d("*UJDQ", forgiving = FALSE, pad = FALSE), " (pad=TRUE:", d("*UJDQ", forgiving = FALSE), ")\n")
cat("pad=FALSE, '\\n' at 3, length 5:  ", d("QU\nJD", forgiving = FALSE, pad = FALSE), " (pad=TRUE:", d("QU\nJD", forgiving = FALSE), ")\n")
cat("pad=FALSE, '*' at 1, '=' at 8:   ", d("*UJDQUI=", forgiving = FALSE, pad = FALSE), " (pad=TRUE:", d("*UJDQUI=", forgiving = FALSE), ")\n")
cat("pad=FALSE, ' ' at 1, '=' at 8:   ", d(" UJDQUI=", forgiving = FALSE, pad = FALSE), " (pad=TRUE:", d(" UJDQUI=", forgiving = FALSE), ")\n")
